def char_type(c):
    if c >= "A" and c <= "Z":
        return "capital"
    if c >= "a" and c <= "z":
        return "small"
    if c >= "0" and c <= "9":
        return "digit"
    return "other"

def strong(pw):
    if len(pw) < 8:
        return False
    cap = False
    small = False
    digit = False
    for i in range(0, len(pw)):
        t = char_type(pw[i])
        if pw[i] == " ":
            return False
        if t == "capital":
            cap = True
        if t == "small":
            small = True
        if t == "digit":
            digit = True
    return cap and small and digit

